import Foundation

let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var componentErrors: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    guard line.hasPrefix("[") else { continue }
    guard let closeBracket = line.firstIndex(of: "]") else { continue }

    let timestamp = String(line[line.index(after: line.startIndex)..<closeBracket])

    let afterBracket = String(line[line.index(after: closeBracket)...])
    let trimmed = afterBracket.trimmingCharacters(in: .whitespaces)

    guard let spaceIdx = trimmed.firstIndex(of: " ") else { continue }
    let level = String(trimmed[trimmed.startIndex..<spaceIdx])

    let afterLevel = trimmed[trimmed.index(after: spaceIdx)...].trimmingCharacters(in: .whitespaces)

    guard afterLevel.hasPrefix("("), let closeParen = afterLevel.firstIndex(of: ")") else { continue }
    let component = String(afterLevel[afterLevel.index(after: afterLevel.startIndex)..<closeParen])

    let afterComponent = afterLevel[afterLevel.index(after: closeParen)...].trimmingCharacters(in: .whitespaces)

    guard afterComponent.hasPrefix("- ") else { continue }
    let message = String(afterComponent.dropFirst(2))

    levelCounts[level, default: 0] += 1

    if level == "ERROR" {
        componentErrors[component, default: 0] += 1
        errorMessages.insert(message)
    }

    let timeParts = timestamp.components(separatedBy: " ")
    if timeParts.count >= 2 {
        let hhmmss = timeParts[1].components(separatedBy: ":")
        if let hour = Int(hhmmss[0]) {
            hourCounts[hour, default: 0] += 1
        }
    }
}

print("=== Log Analysis ===")
print("")

print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}

print("")

if let top = componentErrors.sorted(by: {
    if $0.value != $1.value { return $0.value > $1.value }
    return $0.key < $1.key
}).first {
    print("Component with Most Errors: \(top.key) (\(top.value) errors)")
}

print("")

print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}

print("")

if let top = hourCounts.sorted(by: {
    if $0.value != $1.value { return $0.value > $1.value }
    return $0.key < $1.key
}).first {
    print("Busiest Hour: \(String(format: "%02d:00", top.key)) (\(top.value) entries)")
}

