import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static class Parser {
        private final String input;
        private int pos;

        Parser(String input) {
            this.input = input;
            this.pos = 0;
        }

        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
        }

        private char peek() {
            skipWhitespace();
            if (pos >= input.length()) throw new RuntimeException("Unexpected end of input");
            return input.charAt(pos);
        }

        private char next() {
            skipWhitespace();
            if (pos >= input.length()) throw new RuntimeException("Unexpected end of input");
            return input.charAt(pos++);
        }

        private void expect(char c) {
            char actual = next();
            if (actual != c) throw new RuntimeException("Expected '" + c + "' but got '" + actual + "'");
        }

        Object parse() {
            Object result = parseValue();
            skipWhitespace();
            if (pos < input.length()) throw new RuntimeException("Unexpected trailing content");
            return result;
        }

        Object parseValue() {
            char c = peek();
            switch (c) {
                case '{': return parseObject();
                case '[': return parseArray();
                case '"': return parseString();
                case 't': return parseBoolean();
                case 'f': return parseBoolean();
                case 'n': return parseNull();
                default: return parseNumber();
            }
