use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

struct Parser {
    input: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { input: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) -> Result<(), String> {
        self.skip_whitespace();
        match self.next() {
            Some(ch) if ch == c => Ok(()),
            _ => Err(format!("Expected '{}'", c)),
        }
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Ok(Json::String(self.parse_string()?)),
            Some('t') => self.parse_literal("true", Json::Bool(true)),
            Some('f') => self.parse_literal("false", Json::Bool(false)),
            Some('n') => self.parse_literal("null", Json::Null),
            Some(c) if c == '-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err("Unexpected character".into()),
        }
    }

    fn parse_object(&mut self) -> Result<Json, String> {
        self.expect('{')?;
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Ok(Json::Object(map));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.expect(':')?;
            let value = self.parse_value()?;
            map.insert(key, value);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => return Err("Expected ',' or '}' in object".into()),
            }
        }
        Ok(Json::Object(map))
    }

    fn parse_array(&mut self) -> Result<Json, String> {
        self.expect('[')?;
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Ok(Json::Array(arr));
        }
        loop {
            let value = self.parse_value()?;
            arr.push(value);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => return Err("Expected ',' or ']' in array".into()),
            }
        }
        Ok(Json::Array(arr))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect('"')?;
        let mut s = String::new();
        loop {
            match self.next() {
                None => return Err("Unterminated string".into()),
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('n') => s.push('\n'),
                        Some('r') => s.push('\r'),
                        Some('t') => s.push('\t'),
                        Some('u') => {
                            let mut code: u32 = 0;
                            for _ in 0..4 {
                                let c = self.next().ok_or("Invalid unicode escape")?;
                                code = code * 16 + c.to_digit(16).ok_or("Invalid hex digit")?;
                            }
                            if (0xD800..=0xDBFF).contains(&code) {
                                if self.next() == Some('\\') && self.next() == Some('u') {
                                    let mut low: u32 = 0;
                                    for _ in 0..4 {
                                        let c = self.next().ok_or("Invalid unicode escape")?;
                                        low = low * 16 + c.to_digit(16).ok_or("Invalid hex digit")?;
                                    }
                                    let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                    s.push(char::from_u32(cp).ok_or("Invalid unicode")?);
                                } else {
                                    return Err("Invalid surrogate pair".into());
                                }
                            } else {
                                s.push(char::from_u32(code).ok_or("Invalid unicode")?);
                            }
                        }
                        _ => return Err("Invalid escape sequence".into()),
                    }
                }
                Some(c) => s.push(c),
            }
        }
        Ok(s)
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        if self.peek() == Some('-') {
            self.pos += 1;
        }
        while self.peek().map_or(false, |c| c.is_ascii_digit()) {
            self.pos += 1;
        }
        if self.peek() == Some('.') {
            self.pos += 1;
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
            }
        }
        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.pos += 1;
            if self.peek() == Some('+') || self.peek() == Some('-') {
                self.pos += 1;
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
            }
        }
        let s: String = self.input[start..self.pos].iter().collect();
        s.parse::<f64>().map(Json::Number).map_err(|e| e.to_string())
    }

    fn parse_literal(&mut self, lit: &str, val: Json) -> Result<Json, String> {
        for c in lit.chars() {
            match self.next() {
                Some(ch) if ch == c => {}
                _ => return Err(format!("Expected literal '{}'", lit)),
            }
        }
        Ok(val)
    }
