                        buf[i++] = '?';
                        *p += 4;
                    }
                    break;
                default: buf[i++] = **p; break;
            }
        } else {
            buf[i++] = **p;
        }
        (*p)++;
    }
    if (**p == '"') (*p)++;
    buf[i] = '\0';
    return 1;
}

static int parse_json_number(const char **p, double *out) {
