    close(sock);
    response[total] = '\0';

    char *body = strstr(response, "\r\n\r\n");
    if (body) {
        body += 4;
    } else {
        body = strstr(response, "\n\n");
        if (body) body += 2;
        else body = response;
    }

    Product *products = malloc(MAX_PRODUCTS * sizeof(Product));
    if (!products) {
        perror("malloc products");
        free(response);
        return 1;
    }

    int count = 0;
    const char *p = body;

    while (*p && *p != '[') p++;
    if (*p == '[') p++;

    while (count < MAX_PRODUCTS) {
        skip_ws(&p);
        if (*p == ']' || *p == '\0') break;
        if (*p == ',') { p++; continue; }
        if (*p == '{') {
            if (parse_product(&p, &products[count]))
                count++;
        } else {
            p++;
        }
    }

    free(response);

    Product *filtered = malloc((count > 0 ? count : 1) * sizeof(Product));
    if (!filtered) {
        perror("malloc filtered");
        free(products);
        return 1;
