use std::collections::{BTreeMap, HashMap};
use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut component_errors: HashMap<String, usize> = HashMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: BTreeMap<String, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let bracket_end = line.find(']').expect("No closing bracket");
        let timestamp_part = &line[1..bracket_end];

        // Extract hour (positions 11..13 in "YYYY-MM-DD HH:MM:SS")
        let hour_str = &timestamp_part[11..13];
