    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get(&self, key: &str) -> Option<&JsonValue> {
        if let JsonValue::Object(items) = self {
            for (k, v) in items {
                if k == key {
                    return Some(v);
                }
            }
        }
        None
    }

