                            }
                            self.pos += 4;
                        }
                    }
                    _ => s.push(esc),
                }
                self.pos += 1;
            } else if c == '"' {
                self.pos += 1;
                break;
            } else {
                s.push(c);
                self.pos += 1;
            }
        }
        s
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;
        while self.pos < self.input.len() {
