public class Main {
    static String extractString(String json, String key) {
        String search = "\"" + key + "\"";
        int idx = json.indexOf(search);
        if (idx == -1) return "";
        idx += search.length();
        while (idx < json.length() && json.charAt(idx) != ':') idx++;
        idx++;
        while (idx < json.length() && json.charAt(idx) == ' ') idx++;
        if (idx >= json.length() || json.charAt(idx) != '"') return "";
        idx++;
        int start = idx;
        while (idx < json.length() && json.charAt(idx) != '"') {
            if (json.charAt(idx) == '\\' && idx + 1 < json.length()) idx++;
            idx++;
        }
        return json.substring(start, idx);
    }

    static double extractNumber(String json, String key) {
        String search = "\"" + key + "\"";
        int idx = json.indexOf(search);
        if (idx == -1) return 0.0;
        idx += search.length();
        while (idx < json.length() && json.charAt(idx) != ':') idx++;
        idx++;
        while (idx < json.length() && json.charAt(idx) == ' ') idx++;
        int start = idx;
        while (idx < json.length() && (Character.isDigit(json.charAt(idx)) || json.charAt(idx) == '.' || json.charAt(idx) == '-' || json.charAt(idx) == '+' || json.charAt(idx) == 'e' || json.charAt(idx) == 'E')) {
            idx++;
        }
        return Double.parseDouble(json.substring(start, idx));
    }

    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
