let pathB = "<tmp>"

let dataA = try Data(contentsOf: URL(fileURLWithPath: pathA))
let dataB = try Data(contentsOf: URL(fileURLWithPath: pathB))
let a = try JSONSerialization.jsonObject(with: dataA)
let b = try JSONSerialization.jsonObject(with: dataB)

func canonicalData(_ obj: Any) -> Data? {
    try? JSONSerialization.data(withJSONObject: obj, options: [.sortedKeys])
}

func merge(_ a: Any, _ b: Any) -> Any {
    if let da = a as? [String: Any], let db = b as? [String: Any] {
        var result = da
        for (k, v) in db {
            if let existing = result[k] {
                result[k] = merge(existing, v)
            } else {
                result[k] = v
            }
        }
        return result
    }
    if let aa = a as? [Any], let ba = b as? [Any] {
        var result = aa
        var seen = Set<Int>()
        for item in aa {
            if let d = canonicalData(item) {
                seen.insert(d.hashValue)
            }
        }
        for item in ba {
            if let d = canonicalData(item) {
                if !seen.contains(d.hashValue) {
                    seen.insert(d.hashValue)
                    result.append(item)
                }
            } else {
                result.append(item)
            }
        }
        return result
    }
    return b
}

func escapeString(_ s: String) -> String {
    let data = try! JSONSerialization.data(withJSONObject: [s])
    let str = String(data: data, encoding: .utf8)!
    return String(str.dropFirst().dropLast())
}

func serialize(_ obj: Any, indent: Int) -> String {
    let pad = String(repeating: " ", count: indent)
    let inner = String(repeating: " ", count: indent + 2)

    if let dict = obj as? [String: Any] {
        let keys = dict.keys.sorted()
        if keys.isEmpty { return "{}" }
        var parts: [String] = []
        for k in keys {
            let v = serialize(dict[k]!, indent: indent + 2)
            parts.append("\(inner)\"\(escapeString(k))\": \(v)")
        }
        return "{\n" + parts.joined(separator: ",\n") + "\n\(pad)}"
    }
    if let arr = obj as? [Any] {
        if arr.isEmpty { return "[]" }
        let parts = arr.map { "\(inner)\(serialize($0, indent: indent + 2))" }
        return "[\n" + parts.joined(separator: ",\n") + "\n\(pad)]"
    }
    if let s = obj as? String {
        return escapeString(s)
    }
    if obj is NSNull {
        return "null"
    }
    if let b = obj as? Bool {
        return b ? "true" : "false"
    }
    if let n = obj as? NSNumber {
        let dv = n.doubleValue
        if dv == dv.rounded() && abs(dv) < 1e15 {
            return String(Int64(dv))
        }
        return String(dv)
    }
    return "null"
}

