    FileHandle.standardError.write(Data("Invalid JSON\n".utf8))
    exit(1)
}

let nodes = json["nodes"] as! [String]
let edgesArray = json["edges"] as! [[String: Any]]

var adj: [String: [(String, Double)]] = [:]
for node in nodes {
    adj[node] = []
}

for edge in edgesArray {
    let from = edge["from"] as! String
    let to = edge["to"] as! String
    let weight = (edge["weight"] as? NSNumber)?.doubleValue ?? 0
    adj[from]?.append((to, weight))
    adj[to]?.append((from, weight))
}

let source = "A"
var dist: [String: Double] = [:]
var visited: Set<String> = []

for node in nodes {
    dist[node] = Double.infinity
}
dist[source] = 0

for _ in 0..<nodes.count {
    var minNode: String? = nil
    var minDist = Double.infinity
    for node in nodes {
        if !visited.contains(node) && dist[node]! < minDist {
            minDist = dist[node]!
            minNode = node
        }
