        count++;
    }
    for (int i = 0, j = pos - 1; i < j; i++, j--) {
        char t = buf[i]; buf[i] = buf[j]; buf[j] = t;
    }
    buf[pos] = '\0';
}

static void format_comma_double(double val, char *buf, size_t bufsz) {
    long long intpart = (long long)val;
    long long frac = (long long)((val - (double)intpart) * 100.0 + 0.5);
    if (frac >= 100) { intpart++; frac -= 100; }
    if (frac < 0) { intpart--; frac += 100; }
    char ipart[32];
    format_comma_ll(intpart, ipart, sizeof(ipart));
    snprintf(buf, bufsz, "%s.%02lld", ipart, frac);
}

