#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE 4096

typedef struct {
    char name[256];
    char department[256];
    double salary;
} Employee;

static void trim(char *s) {
    size_t len = strlen(s);
    while (len > 0 && (s[len-1] == ' ' || s[len-1] == '\t' || s[len-1] == '\r' || s[len-1] == '\n'))
        s[--len] = '\0';
    size_t start = 0;
    while (s[start] == ' ' || s[start] == '\t') start++;
    if (start > 0) memmove(s, s + start, len - start + 1);
}

static void format_comma_ll(long long n, char *buf, size_t bufsz) {
    if (n < 0) {
        buf[0] = '-';
        format_comma_ll(-n, buf + 1, bufsz - 1);
        return;
    }
    char tmp[32];
    int len = snprintf(tmp, sizeof(tmp), "%lld", n);
    int pos = 0;
    int count = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (count > 0 && count % 3 == 0) {
            if (pos + 1 < (int)bufsz) buf[pos++] = ',';
        }
        if (pos + 1 < (int)bufsz) buf[pos++] = tmp[i];
        count++;
    }
    for (int i = 0, j = pos - 1; i < j; i++, j--) {
        char t = buf[i]; buf[i] = buf[j]; buf[j] = t;
    }
    buf[pos] = '\0';
}

static void format_comma_double(double val, char *buf, size_t bufsz) {
    long long intpart = (long long)val;
    long long frac = (long long)((val - (double)intpart) * 100.0 + 0.5);
    if (frac >= 100) { intpart++; frac -= 100; }
    if (frac < 0) { intpart--; frac += 100; }
    char ipart[32];
    format_comma_ll(intpart, ipart, sizeof(ipart));
    snprintf(buf, bufsz, "%s.%02lld", ipart, frac);
}

