import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static String s;
    static int pos = 0;

    static void skipWs() {
        while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++;
    }

    static Object parseValue() {
        skipWs();
        char c = s.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        return parseNumber();
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> m = new LinkedHashMap<>();
        pos++; // {
        skipWs();
        if (pos < s.length() && s.charAt(pos) == '}') { pos++; return m; }
        while (true) {
            skipWs();
            String key = parseString();
            skipWs();
            pos++; // :
            Object v = parseValue();
            m.put(key, v);
            skipWs();
            if (pos < s.length() && s.charAt(pos) == ',') { pos++; }
            else { pos++; break; } // }
        }
        return m;
    }

    static List<Object> parseArray() {
        List<Object> l = new ArrayList<>();
        pos++; // [
        skipWs();
        if (pos < s.length() && s.charAt(pos) == ']') { pos++; return l; }
        while (true) {
            l.add(parseValue());
            skipWs();
            if (pos < s.length() && s.charAt(pos) == ',') { pos++; }
            else { pos++; break; } // ]
        }
        return l;
    }

    static String parseString() {
        skipWs();
        pos++; // "
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = s.charAt(pos);
            if (c == '\\') {
                pos++;
                char e = s.charAt(pos);
                if (e == 'n') sb.append('\n');
                else if (e == 't') sb.append('\t');
                else if (e == 'r') sb.append('\r');
                else sb.append(e);
            } else if (c == '"') {
                pos++;
                break;
            } else {
                sb.append(c);
            }
            pos++;
        }
        return sb.toString();
    }

    static Object parseNumber() {
        skipWs();
        int start = pos;
        while (pos < s.length() && (Character.isDigit(s.charAt(pos)) || s.charAt(pos) == '-'
                || s.charAt(pos) == '+' || s.charAt(pos) == '.' || s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
            pos++;
        }
        String num = s.substring(start, pos);
        if (num.contains(".") || num.contains("e") || num.contains("E"))
            return (Object) Double.parseDouble(num);
        return (Object) Long.parseLong(num);
    }

    static String fmt(double d) {
        if (d == Math.floor(d) && !Double.isInfinite(d)) {
            return String.valueOf((long) d);
        }
        return String.valueOf(d);
    }

    public static void main(String[] args) throws Exception {
        String content = new String(Files.readAllBytes(
                Paths.get("<tmp>")));
        s = content;
        pos = 0;
        Map<String, Object> root = (Map<String, Object>) parseValue();

        List<String> nodes = new ArrayList<>();
        for (Object n : (List<Object>) root.get("nodes")) nodes.add((String) n);

        Map<String, Map<String, Double>> adj = new HashMap<>();
        for (String n : nodes) adj.put(n, new HashMap<>());

        for (Object e : (List<Object>) root.get("edges")) {
            Map<String, Object> em = (Map<String, Object>) e;
            String from = (String) em.get("from");
            String to = (String) em.get("to");
            double w = ((Number) em.get("weight")).doubleValue();
            adj.computeIfAbsent(from, k -> new HashMap<>()).put(to, w);
            adj.computeIfAbsent(to, k -> new HashMap<>()).put(from, w);
        }

        Map<String, Double> dist = new HashMap<>();
        for (String n : nodes) dist.put(n, Double.POSITIVE_INFINITY);
        dist.put("A", 0.0);

        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[0]));
        Map<String, Integer> idx = new HashMap<>();
        for (int i = 0; i < nodes.size(); i++) idx.put(nodes.get(i), i);

        pq.add(new double[]{0.0, idx.get("A")});

        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            double d = cur[0];
            String u = nodes.get((int) cur[1]);
            if (d > dist.get(u)) continue;
            for (Map.Entry<String, Double> e : adj.get(u).entrySet()) {
                String v = e.getKey();
                double nd = d + e.getValue();
                if (nd < dist.get(v)) {
                    dist.put(v, nd);
                    pq.add(new double[]{nd, idx.get(v)});
                }
            }
        }

        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String n : sorted) {
            double d = dist.get(n);
            String ds = Double.isInfinite(d) ? "unreachable" : fmt(d);
            System.out.println("A -> " + n + ": " + ds);
        }
    }
}

