import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(content: Buffer): number {
  if (content.length === 0) return 0;
  let newlines = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 10) newlines++;
  }
  const endsWithNewline = content[content.length - 1] === 10;
  return newlines + (endsWithNewline ? 0 : 1);
}

function walkDir(dir: string, root: string, visited: Set<string>, results: Map<string, FileInfo[]>): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let resolved: string;
      try {
        resolved = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(resolved)) continue;
      visited.add(resolved);
      walkDir(fullPath, root, visited, results);
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      const content = fs.readFileSync(fullPath);
      const lines = countLines(content);
      const chars = content.length;
      const ext = path.extname(entry.name);

      if (!results.has(ext)) {
        results.set(ext, []);
      }
      results.get(ext)!.push({ relativePath, lines, chars });
    }
  }
}

const visited = new Set<string>();
try {
  visited.add(fs.realpathSync(rootDir));
} catch {
  visited.add(rootDir);
}

const results = new Map<string, FileInfo[]>();
walkDir(rootDir, rootDir, visited, results);

const extensions = Array.from(results.keys()).sort();

for (const ext of extensions) {
  const files = results.get(ext)!;
  files.sort((a, b) => a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0);
}

let output = '=== File Tree Analysis ===\n';
output += '\n';

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of extensions) {
  const files = results.get(ext)!;
  const extTotalLines = files.reduce((sum, f) => sum + f.lines, 0);
  const extTotalChars = files.reduce((sum, f) => sum + f.chars, 0);

  output += `Extension: ${ext}\n`;
  output += `  Files: ${files.length}\n`;
  output += `  Total Lines: ${extTotalLines}\n`;
  output += `  Total Characters: ${extTotalChars}\n`;

  for (const file of files) {
    output += `    ${file.relativePath}: ${file.lines} lines, ${file.chars} chars\n`;
  }

  totalFiles += files.length;
  totalLines += extTotalLines;
  totalChars += extTotalChars;
}

output += '\n';
output += `Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

process.stdout.write(output);

