import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<String[]>> extMap = new TreeMap<>();
        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        List<Path> files = Files.walk(root)
            .filter(p -> Files.isRegularFile(p) && !Files.isSymbolicLink(p))
            .sorted()
            .collect(Collectors.toList());

        for (Path file : files) {
            String relPath = root.relativize(file).toString().replace('\\', '/');

            String fileName = file.getFileName().toString();
            String ext = "";
            int lastDot = fileName.lastIndexOf('.');
            if (lastDot > 0) {
                ext = fileName.substring(lastDot);
            }

            byte[] content = Files.readAllBytes(file);
            long chars = content.length;
            long lines = 0;
            if (content.length > 0) {
                for (byte b : content) {
                    if (b == '\n') lines++;
                }
                if (content[content.length - 1] != '\n') {
                    lines++;
                }
            }

            extMap.computeIfAbsent(ext, k -> new ArrayList<>())
                .add(new String[]{relPath, String.valueOf(lines), String.valueOf(chars)});

            totalFiles++;
            totalLines += lines;
            totalChars += chars;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> filesList = entry.getValue();

            filesList.sort(Comparator.comparing(a -> a[0]));

            long extLines = 0;
            long extChars = 0;
            for (String[] f : filesList) {
                extLines += Long.parseLong(f[1]);
                extChars += Long.parseLong(f[2]);
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(filesList.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (String[] f : filesList) {
                sb.append("    ").append(f[0]).append(": ").append(f[1]).append(" lines, ").append(f[2]).append(" chars\n");
            }
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }
}

