fn print_matrix(m: &Vec<Vec<i64>>) {
    for row in m {
        let mut s = "  ".to_string();
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                s.push(' ');
            }
            s.push_str(&format!("{:4}", v));
        }
        println!("{}", s);
    }
}

fn matrix_mul(a: &Vec<Vec<i64>>, b: &Vec<Vec<i64>>, n: usize) -> Vec<Vec<i64>> {
    let mut c = vec![vec![0i64; n]; n];
    for i in 0..n {
        for j in 0..n {
            for k in 0..n {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }
    c
}

fn determinant(m: &Vec<Vec<i64>>, n: usize) -> i64 {
    if n == 1 {
        return m[0][0];
    }
    let mut det = 0i64;
    for j in 0..n {
        let mut minor = vec![vec![0i64; n - 1]; n - 1];
        for i in 0..n - 1 {
            for k in 0..n - 1 {
                let src_col = if k < j { k } else { k + 1 };
                minor[i][k] = m[i + 1][src_col];
            }
        }
        let sign = if j % 2 == 0 { 1 } else { -1 };
        det += sign * m[0][j] * determinant(&minor, n - 1);
    }
    det
}

