#define BASE_DIR "<tmp>"

typedef struct {
    char *relpath;
    long lines;
    long chars;
} FileInfo;

static FileInfo *files = NULL;
static int file_count = 0;
static int file_cap = 0;

static void add_file(const char *relpath, long lines, long chars) {
    if (file_count >= file_cap) {
        file_cap = file_cap ? file_cap * 2 : 128;
        files = realloc(files, (size_t)file_cap * sizeof(FileInfo));
        if (!files) { fprintf(stderr, "out of memory\n"); exit(1); }
    }
    files[file_count].relpath = strdup(relpath);
    if (!files[file_count].relpath) { fprintf(stderr, "out of memory\n"); exit(1); }
    files[file_count].lines = lines;
    files[file_count].chars = chars;
    file_count++;
}

static long count_lines(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return 0;
    long count = 0;
    char *buf = malloc(65536);
    if (!buf) { fclose(f); return 0; }
    size_t n;
    while ((n = fread(buf, 1, 65536, f)) > 0) {
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') count++;
        }
    }
    free(buf);
    fclose(f);
    return count;
}

static const char *get_filename(const char *path) {
    const char *slash = strrchr(path, '/');
    return slash ? slash + 1 : path;
}

static const char *get_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (dot && dot != filename) return dot;
    return "(no ext)";
}

static int cmp_files(const void *a, const void *b) {
    const FileInfo *fa = (const FileInfo *)a;
    const FileInfo *fb = (const FileInfo *)b;
    const char *ea = get_extension(get_filename(fa->relpath));
    const char *eb = get_extension(get_filename(fb->relpath));
    int r = strcmp(ea, eb);
    if (r != 0) return r;
    return strcmp(fa->relpath, fb->relpath);
}

static void walk(const char *dirpath, const char *relpath) {
    DIR *dir = opendir(dirpath);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        size_t dlen = strlen(dirpath);
        size_t nlen = strlen(entry->d_name);
        char *fullpath = malloc(dlen + 1 + nlen + 1);
        if (!fullpath) { closedir(dir); return; }
        sprintf(fullpath, "%s/%s", dirpath, entry->d_name);

        char *rel;
        if (relpath[0] == '\0') {
            rel = strdup(entry->d_name);
        } else {
            size_t rlen = strlen(relpath);
            rel = malloc(rlen + 1 + nlen + 1);
            if (rel) sprintf(rel, "%s/%s", relpath, entry->d_name);
        }
        if (!rel) { free(fullpath); closedir(dir); return; }

        struct stat st;
        if (lstat(fullpath, &st) == 0) {
            if (S_ISLNK(st.st_mode)) {
                /* skip symlinks entirely */
            } else if (S_ISREG(st.st_mode)) {
                long lines = count_lines(fullpath);
                long chars = (long)st.st_size;
                add_file(rel, lines, chars);
            } else if (S_ISDIR(st.st_mode)) {
                walk(fullpath, rel);
            }
        }

        free(fullpath);
        free(rel);
    }
    closedir(dir);
}

int main(void) {
    struct stat st;
    if (lstat(BASE_DIR, &st) == 0 && S_ISDIR(st.st_mode)) {
        walk(BASE_DIR, "");
