    if (file_count > 1) {
        qsort(files, (size_t)file_count, sizeof(FileInfo), cmp_files);
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0, total_lines = 0, total_chars = 0;

    int i = 0;
