        int j = i;
        while (j < file_count) {
            const char *extj = get_extension(get_filename(files[j].relpath));
            if (strcmp(ext, extj) != 0) break;
            g_lines += files[j].lines;
            g_chars += files[j].chars;
            g_count++;
            j++;
        }

        printf("Extension: %s\n", ext);
        printf("  Files: %ld\n", (long)g_count);
        printf("  Total Lines: %ld\n", g_lines);
        printf("  Total Characters: %ld\n", g_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n",
                   files[k].relpath, files[k].lines, files[k].chars);
        }

        total_files += (long)g_count;
        total_lines += g_lines;
        total_chars += g_chars;
        i = j;
    }

    printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n",
           total_files, total_lines, total_chars);

    for (int k = 0; k < file_count; k++) free(files[k].relpath);
    free(files);

    return 0;
}

