#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value {
    json_type type;
    int bool_val;
    double num_val;
    char *num_str;
    char *str_val;
    struct json_value **items;
    int item_count;
    int item_cap;
    char **keys;
    struct json_value **values;
    int pair_count;
    int pair_cap;
} json_value;

typedef struct {
    const char *buf;
    int pos;
    int len;
    int error;
} parser;

static json_value *json_new(json_type t) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    if (!v) { fprintf(stderr, "OOM\n"); exit(1); }
    v->type = t;
    return v;
}

static void json_free(json_value *v) {
    if (!v) return;
    if (v->str_val) free(v->str_val);
    if (v->num_str) free(v->num_str);
    if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->item_count; i++) json_free(v->items[i]);
        free(v->items);
    } else if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->pair_count; i++) {
            free(v->keys[i]);
            json_free(v->values[i]);
        }
        free(v->keys);
        free(v->values);
    }
    free(v);
}

static void parser_skip_ws(parser *p) {
    while (p->pos < p->len && (p->buf[p->pos] == ' ' || p->buf[p->pos] == '\t' ||
           p->buf[p->pos] == '\n' || p->buf[p->pos] == '\r'))
        p->pos++;
}

static char *parse_string_raw(parser *p) {
    if (p->pos >= p->len || p->buf[p->pos] != '"') { p->error = 1; return NULL; }
    p->pos++;
    int cap = 64;
    char *s = (char *)malloc(cap);
    if (!s) { p->error = 1; return NULL; }
    int len = 0;
    while (p->pos < p->len && p->buf[p->pos] != '"') {
        char c = p->buf[p->pos];
        if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) { p->error = 1; free(s); return NULL; }
            char e = p->buf[p->pos];
            char out = 0;
            switch (e) {
                case '"': out = '"'; break;
                case '\\': out = '\\'; break;
                case '/': out = '/'; break;
                case 'b': out = '\b'; break;
                case 'f': out = '\f'; break;
                case 'n': out = '\n'; break;
                case 'r': out = '\r'; break;
                case 't': out = '\t'; break;
                case 'u': {
                    if (p->pos + 4 >= p->len) { p->error = 1; free(s); return NULL; }
                    char hex[5];
                    memcpy(hex, p->buf + p->pos + 1, 4);
                    hex[4] = 0;
                    unsigned int cp = (unsigned int)strtoul(hex, NULL, 16);
                    p->pos += 4;
                    /* encode as UTF-8 */
                    if (cp < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
                        s[len++] = (char)cp;
                    } else if (cp < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
                        s[len++] = (char)(0xC0 | (cp >> 6));
                        s[len++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
                        s[len++] = (char)(0xE0 | (cp >> 12));
                        s[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        s[len++] = (char)(0x80 | (cp & 0x3F));
                    }
                    continue;
                }
                default: p->error = 1; free(s); return NULL;
            }
            p->pos++;
            if (len + 1 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
            s[len++] = out;
        } else {
            if (len + 1 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
            s[len++] = c;
            p->pos++;
        }
    }
    if (p->pos >= p->len) { p->error = 1; free(s); return NULL; }
    p->pos++; /* closing quote */
    if (len + 1 >= cap) { cap = len + 1; s = (char *)realloc(s, cap); }
    s[len] = 0;
    return s;
}

static json_value *parse_value(parser *p);

static json_value *parse_number(parser *p) {
    int start = p->pos;
    if (p->pos < p->len && (p->buf[p->pos] == '-' || p->buf[p->pos] == '+')) p->pos++;
    while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    if (p->pos < p->len && p->buf[p->pos] == '.') {
        p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    if (p->pos < p->len && (p->buf[p->pos] == 'e' || p->buf[p->pos] == 'E')) {
        p->pos++;
        if (p->pos < p->len && (p->buf[p->pos] == '-' || p->buf[p->pos] == '+')) p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    int nlen = p->pos - start;
    char *ns = (char *)malloc(nlen + 1);
    if (!ns) { p->error = 1; return NULL; }
    memcpy(ns, p->buf + start, nlen);
    ns[nlen] = 0;
    json_value *v = json_new(JSON_NUMBER);
    v->num_val = strtod(ns, NULL);
    v->num_str = ns;
    return v;
}

static json_value *parse_array(parser *p) {
    p->pos++; /* [ */
    json_value *v = json_new(JSON_ARRAY);
    v->item_cap = 8;
    v->items = (json_value **)calloc(v->item_cap, sizeof(json_value *));
    parser_skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == ']') {
        p->pos++;
        return v;
    }
    while (1) {
        parser_skip_ws(p);
        json_value *item = parse_value(p);
        if (p->error) { json_free(v); return NULL; }
        if (v->item_count >= v->item_cap) {
            v->item_cap *= 2;
            v->items = (json_value **)realloc(v->items, v->item_cap * sizeof(json_value *));
        }
        v->items[v->item_count++] = item;
        parser_skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            p->error = 1;
            json_free(v);
            return NULL;
        }
    }
    return v;
}

static void obj_add_pair(json_value *v, char *key, json_value *val) {
    if (v->pair_count >= v->pair_cap) {
