static void print_string_escaped(const char *s, FILE *f) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (c < 0x20) {
                    fprintf(f, "\\u%04x", c);
                } else {
                    fputc(c, f);
                }
        }
    }
    fputc('"', f);
}

static void print_number(double val, const char *num_str, FILE *f) {
    if (num_str) {
        /* check if it looks like an integer (no ., e, E) */
        int is_int = 1;
        for (const char *p = num_str; *p; p++) {
            if (*p == '.' || *p == 'e' || *p == 'E') { is_int = 0; break; }
        }
        if (is_int) {
            /* print as integer to avoid trailing .0 */
            long long ival = (long long)val;
            fprintf(f, "%lld", ival);
        } else {
            /* print the original string */
            fputs(num_str, f);
        }
    } else {
        if (val == (long long)val && fabs(val) < 1e15) {
            fprintf(f, "%lld", (long long)val);
        } else {
            fprintf(f, "%.15g", val);
        }
    }
}

static void print_json(json_value *v, int indent, FILE *f) {
    switch (v->type) {
        case JSON_NULL:
            fputs("null", f);
            break;
        case JSON_BOOL:
            fputs(v->bool_val ? "true" : "false", f);
            break;
        case JSON_NUMBER:
            print_number(v->num_val, v->num_str, f);
            break;
        case JSON_STRING:
            print_string_escaped(v->str_val, f);
            break;
        case JSON_ARRAY: {
            if (v->item_count == 0) {
                fputs("[]", f);
                return;
            }
            fputs("[\n", f);
            for (int i = 0; i < v->item_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', f);
                print_json(v->items[i], indent + 1, f);
                if (i < v->item_count - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', f);
            fputs("]", f);
            break;
        }
        case JSON_OBJECT: {
            if (v->pair_count == 0) {
                fputs("{}", f);
                return;
            }
            /* sort keys */
            int n = v->pair_count;
            /* create index array for sorting */
            int *idx = (int *)malloc(n * sizeof(int));
            for (int i = 0; i < n; i++) idx[i] = i;
            /* simple insertion sort by key */
            for (int i = 1; i < n; i++) {
                int key_idx = idx[i];
                int j = i - 1;
                while (j >= 0 && strcmp(v->keys[idx[j]], v->keys[key_idx]) > 0) {
                    idx[j + 1] = idx[j];
                    j--;
                }
                idx[j + 1] = key_idx;
            }
            fputs("{\n", f);
            for (int i = 0; i < n; i++) {
                int ki = idx[i];
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', f);
                print_string_escaped(v->keys[ki], f);
                fputs(": ", f);
                print_json(v->values[ki], indent + 1, f);
                if (i < n - 1) fputc(',', f);
                fputc('\n', f);
            }
            free(idx);
            for (int s = 0; s < indent * 2; s++) fputc(' ', f);
            fputs("}", f);
            break;
        }
    }
}

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (!buf) { fclose(f); fprintf(stderr, "OOM\n"); exit(1); }
    size_t rd = fread(buf, 1, sz, f);
    fclose(f);
    buf[rd] = 0;
    *out_len = (int)rd;
    return buf;
}

