import Foundation

let baseDir = "<tmp>"
let fileManager = FileManager.default

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var files: [String: [FileInfo]] = [:]
var visitedDirs: Set<String> = []

func isSymlink(_ path: String) -> Bool {
    do {
        _ = try fileManager.destinationOfSymbolicLink(atPath: path)
        return true
    } catch {
        return false
    }
}

func walk(dir: String) {
    let resolvedDir = (dir as NSString).standardizingPath
    if visitedDirs.contains(resolvedDir) { return }
    visitedDirs.insert(resolvedDir)

    guard let contents = fileManager.contentsOfDirectory(atPath: dir) else { return }

    for name in contents {
        let fullPath = dir + "/" + name

        if isSymlink(fullPath) {
            continue
        }

        var isDir: ObjCBool = false
        guard fileManager.fileExists(atPath: fullPath, isDirectory: &isDir) else { continue }

        if isDir.boolValue {
            walk(dir: fullPath)
        } else {
            let relativePath = String(fullPath.dropFirst(baseDir.count + 1))

            let data = fileManager.contents(atPath: fullPath) ?? Data()
            let chars = data.count

            let lines: Int
            if data.isEmpty {
                lines = 0
            } else {
                var lineCount = 0
                for byte in data {
                    if byte == 10 {
                        lineCount += 1
                    }
                }
                if data[data.count - 1] != 10 {
                    lineCount += 1
                }
                lines = lineCount
            }

            let ext = (fullPath as NSString).pathExtension
            let extKey = ext.isEmpty ? "" : "." + ext
            var info = files[extKey, default: []]
            info.append(FileInfo(relativePath: relativePath, lines: lines, chars: chars))
            files[extKey] = info
        }
    }
}

