func multiply(_ M1: [[Int]], _ M2: [[Int]]) -> [[Int]] {
    let rows = M1.count
    let cols = M2[0].count
    let inner = M1[0].count
    var result = [[Int]](repeating: [Int](repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            for k in 0..<inner {
                result[i][j] += M1[i][k] * M2[k][j]
            }
        }
    }
    return result
}

