use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();
    for (rel_path, lines, chars) in &files {
        let p = Path::new(rel_path);
        let ext = p.extension()
            .map(|e| format!(".{}", e))
            .unwrap_or_else(|| "(no extension)".to_string());
        groups.entry(ext).or_default().push((rel_path.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0u64;
    let mut total_lines = 0u64;
    let mut total_chars = 0u64;

    for (ext, file_list) in &groups {
        let n = file_list.len() as u64;
        let lines: u64 = file_list.iter().map(|f| f.1).sum();
        let chars: u64 = file_list.iter().map(|f| f.2).sum();

        println!("Extension: {}", ext);
        println!("  Files: {}", n);
        println!("  Total Lines: {}", lines);
        println!("  Total Characters: {}", chars);

        for (rel_path, l, c) in file_list {
            println!("    {}: {} lines, {} chars", rel_path, l, c);
        }

        total_files += n;
        total_lines += lines;
        total_chars += chars;
    }

    println!();
