const A: number[][] = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
const B: number[][] = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];

function multiply(M: number[][], N: number[][]): number[][] {
    const size = M.length;
    const result: number[][] = Array.from({ length: size }, () => Array(size).fill(0));
    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            for (let k = 0; k < size; k++) {
                result[i][j] += M[i][k] * N[k][j];
            }
        }
    }
    return result;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = [];
        for (let i = 1; i < n; i++) {
            const row: number[] = [];
            for (let k = 0; k < n; k++) {
                if (k !== j) row.push(M[i][k]);
            }
            minor.push(row);
        }
        det += (j % 2 === 0 ? 1 : -1) * M[0][j] * determinant(minor);
    }
    return det;
}

function formatMatrix(M: number[][]): string {
    return M.map(row => "  " + row.map(v => v.toString().padStart(4)).join(" ")).join("\n");
}

