    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser { s: input.chars().collect(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.s.len() && self.s[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.s.get(self.pos).copied()
    }

    fn expect(&mut self, c: char) {
        self.skip_ws();
        assert_eq!(self.peek(), Some(c), "Expected '{}' at pos {}", c, self.pos);
        self.pos += 1;
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::Str(self.parse_string()),
            Some('t') => { self.pos += 4; Json::Bool(true) }
            Some('f') => { self.pos += 5; Json::Bool(false) }
            Some('n') => { self.pos += 4; Json::Null }
            _ => Json::Num(self.parse_number()),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') {
            self.pos += 1;
            return Json::Object(items);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            items.push((key, val));
            self.skip_ws();
            if self.peek() == Some(',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.expect('}');
        Json::Object(items)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') {
            self.pos += 1;
            return Json::Array(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_ws();
            if self.peek() == Some(',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.expect(']');
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut result = String::new();
        loop {
            let c = self.s[self.pos];
            self.pos += 1;
            if c == '"' {
                break;
            }
            if c == '\\' {
                let esc = self.s[self.pos];
                self.pos += 1;
                match esc {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'n' => result.push('\n'),
                    't' => result.push('\t'),
                    'r' => result.push('\r'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'u' => {
                        let hex: String = self.s[self.pos..self.pos + 4].iter().collect();
                        self.pos += 4;
                        let code = u32::from_str_radix(&hex, 16).unwrap();
                        result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => result.push(esc),
                }
            } else {
                result.push(c);
            }
        }
        result
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_ws();
        let start = self.pos;
        if self.peek() == Some('-') {
            self.pos += 1;
        }
        while self.pos < self.s.len() {
            let c = self.s[self.pos];
            if c.is_ascii_digit() || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let num_str: String = self.s[start..self.pos].iter().collect();
        num_str.parse::<f64>().unwrap_or(0.0)
    }
}

fn parse_graph(content: &str) -> (Vec<String>, Vec<(String, String, f64)>) {
    let mut parser = Parser::new(content);
    let root = parser.parse_value();

    let mut nodes = Vec::new();
    let mut edges = Vec::new();

    if let Json::Object(items) = root {
        for (key, val) in &items {
            if key == "nodes" {
                if let Json::Array(arr) = val {
                    for item in arr {
                        if let Json::Str(s) = item {
                            nodes.push(s.clone());
                        }
                    }
                }
            } else if key == "edges" {
                if let Json::Array(arr) = val {
                    for item in arr {
                        if let Json::Object(obj) = item {
                            let mut from = String::new();
                            let mut to = String::new();
                            let mut weight = 0.0f64;
                            for (k, v) in obj {
                                if k == "from" {
                                    if let Json::Str(s) = v { from = s.clone(); }
                                } else if k == "to" {
                                    if let Json::Str(s) = v { to = s.clone(); }
                                } else if k == "weight" {
                                    if let Json::Num(n) = v { weight = *n; }
                                }
                            }
                            edges.push((from, to, weight));
                        }
                    }
                }
            }
        }
    }

    (nodes, edges)
}
